(function(E){ const x = E["ai-m1"] = E["ai-m1"] || {units:{}}; x.units["ai-3"] = {"grammar":{"id":"c-ai-3-g","level":"B1","course":"ai-internet","unit":"ai-3","title":"Rules at work: must not, have to, it's safe to","titleTr":"İş kuralları: must not, have to, it's safe to","titleFa":"قواعد کاری: must not، have to، it's safe to","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["must not + verb","We must not paste customer names."],["have to + verb","I have to remove the phone number first."],["It's safe to + verb","It's safe to paste the public price list."]]},"wrong":"You don't have to paste passwords, it is forbidden.","right":"You must not paste passwords.","blank":{"sentence":"You ___ paste a contract into a public tool.","word":"must not","distractors":["don't have to","must to"]},"wrong2":"We must to remove the names.","right2":"We have to remove the names.","blank2":{"sentence":"I ___ replace the names before I paste this.","word":"have to","distractors":["must to","have"]},"expParts":{"tryFrom":"blank","rule":[{"en":"must not means it is forbidden.","tr":"must not yasak demektir.","fa":"must not یعنی ممنوع است.","ex":"You must not share this password."},{"en":"don't have to means it is not necessary.","tr":"don't have to gerekli değil demektir.","fa":"don't have to یعنی لازم نیست.","ex":"You don't have to turn it off."}],"test":{"en":"Is it forbidden? Use must not.","tr":"Yasak mı? must not kullan.","fa":"ممنوع است؟ از must not استفاده کن."}},"errorWatch":[{"find":["must to"],"fix":{"en":"After must, use the base verb, with no to.","tr":"must'tan sonra to olmadan yalın fiil gelir.","fa":"بعد از must شکل ساده‌ی فعل بدون to بیاور."}}]},"b2":{"id":"c-ai-3-b2","level":"B2","course":"ai-internet","unit":"ai-3","track":"B2","title":"Stating a policy: be not allowed to, unless","titleTr":"Politika belirtmek: be not allowed to, unless","titleFa":"بیان مقررات: be not allowed to، unless","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["be not allowed to","Staff are not allowed to paste contracts."],["unless + present","Don't share it unless your manager agrees."]]},"wrong":"Don't share it unless your manager doesn't agree.","right":"Don't share it unless your manager agrees.","blank":{"sentence":"Staff are not ___ to share client files.","word":"allowed","distractors":["allow","allowing"]},"wrong2":"We are not allow to upload it.","right2":"We are not allowed to upload it.","blank2":{"sentence":"Don't paste it ___ it is public.","word":"unless","distractors":["except","if not to"]},"expParts":{"tryFrom":"blank","rule":[{"en":"be not allowed to is a formal rule.","tr":"be not allowed to resmî bir kuraldır.","fa":"با be not allowed to یک قاعده‌ی رسمی را می‌گویی.","ex":"We are not allowed to upload it."},{"en":"unless means except if.","tr":"unless \"-medikçe\" demektir.","fa":"unless یعنی مگر اینکه.","ex":"Don't upload it unless it is public."}],"test":{"en":"Can you say \"except if\"? Use unless.","tr":"\"except if\" diyebiliyor musun? unless kullan.","fa":"می‌توانی «except if» بگویی؟ از unless استفاده کن."}},"errorWatch":[{"find":["not allow to"],"fix":{"en":"Use the -ed form: not allowed to.","tr":"-ed biçimini kullan: not allowed to.","fa":"از شکل ‎-ed استفاده کن: not allowed to."}}],"useIn":{"en":"B2: add one policy sentence with unless to your prompt note.","tr":"B2: Prompt notuna unless içeren bir kural cümlesi ekle.","fa":"B2: به یادداشت پرامپتت یک جمله با unless برای بیان قاعده اضافه کن."},"exitItem":{"from":"ai-3","kind":"blank","prompt":"We are ___ to upload contracts to outside tools.","options":["not allowed","not allow","don't allow"],"correct":0,"why":{"en":"not allowed: 'We are not allowed to' is a rule about us. 'Not allow' drops -ed, and 'are don't allow' mixes two verbs.","tr":"not allowed: 'We are not allowed to' bizimle ilgili bir kuraldır. 'Not allow' -ed'i düşürür; 'are don't allow' iki fiili karıştırır.","fa":"not allowed درست است، چون We are not allowed to قانونی درباره‌ی ماست. not allow ‎-ed ندارد و are don't allow دو فعل را قاطی می‌کند."}}},"vocab":{"id":"c-ai-3-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-3","goals":["career"],"title":{"en":"Privacy words","tr":"Gizlilik kelimeleri","fa":"کلمه‌های حریم خصوصی"},"cards":[{"word":"Keep activity","sentence":"Keep activity saves your chats.","meaning":{"en":"Saves your chats in your activity. They can be used to improve Google's services, and people may review some of them.","tr":"Sohbetlerini etkinliğine kaydeder. Google hizmetlerini geliştirmek için kullanılabilirler ve bazılarını insanlar inceleyebilir.","fa":"چت‌هایت را در فعالیتت نگه می‌دارد. ممکن است برای بهتر کردن سرویس‌های گوگل استفاده شوند و بعضی از آن‌ها را افرادی بازبینی کنند."}},{"word":"Temporary chat","sentence":"A temporary chat is kept only for a short time.","meaning":{"en":"A chat kept only for a short time and not used to train the AI models","tr":"Yalnızca kısa süre saklanan ve yapay zekâ modellerini eğitmek için kullanılmayan sohbet","fa":"چتی که فقط مدت کوتاهی نگه داشته می‌شود و برای آموزش مدل‌ها استفاده نمی‌شود"}},{"word":"Connected Apps","sentence":"Use Connected Apps only if your company allows it.","meaning":{"en":"Lets Gemini use other services, such as Gmail, with your permission","tr":"İzninle Gemini'ın Gmail gibi başka hizmetleri kullanmasını sağlar","fa":"با اجازه‌ی تو، Gemini می‌تواند از سرویس‌های دیگر مثل Gmail استفاده کند"}},{"word":"personal data","sentence":"A phone number is personal data.","meaning":{"en":"Information about a real person.","tr":"Gerçek bir kişiye ait bilgi.","fa":"اطلاعات مربوط به یک آدم واقعی."}},{"word":"confidential","sentence":"This price list is confidential.","meaning":{"en":"Secret, only for certain people.","tr":"Gizli, yalnızca belirli kişiler için.","fa":"محرمانه، فقط برای افراد مشخص."}},{"word":"placeholder","sentence":"Use a placeholder such as [Customer].","meaning":{"en":"A label that stands for a real detail.","tr":"Gerçek bilginin yerini tutan etiket.","fa":"برچسبی که به‌جای جزئیات واقعی می‌آید."}}]},"judge":{"id":"c-ai-3-j","course":"ai-internet","unit":"ai-3","type":"judge","title":{"en":"Paste it, or fix it first?","tr":"Yapıştır mı, önce düzelt mi?","fa":"بچسبانی یا اول درستش کنی؟"},"prompt":"Is each text safe to paste?","parts":["Safe to paste","Replace details first","Keep it out"],"instruction":{"en":"Choose one answer for each text.","tr":"Her metin için bir cevap seç.","fa":"برای هر متن یک جواب انتخاب کن."},"mode":"single","screen":{"id":"scr-gemini-1","src":"courses/ai-internet/assets/scr-gemini-1.webp?v=3fa4ab578f","alt":"Our drawing of a Gemini-style chat screen, November 2026, not a screenshot. Menu and New chat at the top, a Keep activity switch in settings, a text box at the bottom with Add files and Submit."},"items":[{"by":"Example text","answer":"Our public opening hours are 9:00 to 18:00.","present":["Safe to paste"],"fix":{"en":"It is already public.","tr":"Zaten herkese açık.","fa":"این از قبل عمومی است."}},{"by":"Example text","answer":"Murat Demir called about his unpaid bill.","present":["Replace details first"],"fix":{"en":"Use [Customer] and keep the rest.","tr":"[Customer] yaz, gerisi kalsın.","fa":"از [Customer] استفاده کن و بقیه را نگه دار."}},{"by":"Example text","answer":"The login is admin and the password is 7741.","present":["Keep it out"],"fix":{"en":"Passwords never go into any tool.","tr":"Parolalar hiçbir araca girmez.","fa":"رمز عبور را هرگز وارد هیچ ابزاری نکن."}},{"by":"Example text","answer":"Our full contract with the supplier, with prices.","present":["Keep it out"],"fix":{"en":"A contract with prices is confidential. Ask your company first.","tr":"Fiyatlı sözleşme gizlidir. Önce şirketine sor.","fa":"قرارداد با قیمت محرمانه است. اول از شرکتت بپرس."}}]},"branch":{"id":"c-ai-3-br","course":"ai-internet","unit":"ai-3","type":"branch","title":{"en":"A colleague wants to paste a file","tr":"Bir meslektaşın dosya yapıştırmak istiyor","fa":"همکارت می‌خواهد فایلی را بچسباند"},"setting":{"en":"A short chat at work. Choose what you say.","tr":"İş yerinde kısa bir sohbet. Ne söyleyeceğini seç.","fa":"یک گفت‌وگوی کوتاه در محل کار. انتخاب کن چه بگویی."},"start":"n1","nodes":{"n1":{"speaker":"Colleague","line":"I'll paste the whole customer list into the tool. It's faster.","choices":[{"tone":"good","text":"Please don't. We must not paste customer data. Let's use placeholders.","next":"n2","reply":"You're right, but it takes longer.","feedback":{"en":"Clear, and it gives a way forward.","tr":"Açık ve bir çözüm sunuyor.","fa":"روشن است و راه‌حل هم می‌دهد."}},{"tone":"ok","text":"Maybe check with your manager first.","next":"n2","reply":"I think it's fine, though.","feedback":{"en":"Good, but say what the rule is too.","tr":"İyi ama kuralı da söyle.","fa":"خوب است، ولی قاعده را هم بگو."}},{"tone":"poor","text":"Sure, it's quicker.","next":"n1","reply":"Are you sure? It has phone numbers.","feedback":{"en":"Real people's data would go into the tool.","tr":"Gerçek kişilerin bilgileri araca girer.","fa":"اطلاعات آدم‌های واقعی وارد ابزار می‌شود."}}]},"n2":{"speaker":"Colleague","line":"But the tool has a setting for that, doesn't it?","choices":[{"tone":"good","text":"A setting is not a guarantee. Take the private details out first.","next":"end","reply":"OK. I'll replace the names first.","feedback":{"en":"This is the main idea of the lesson.","tr":"Dersin ana fikri bu.","fa":"این ایده‌ی اصلی درس است."}},{"tone":"ok","text":"I'm not sure. Let's read the privacy page.","next":"end","reply":"OK. Let's read it together.","feedback":{"en":"A fair step, but the habit still comes first.","tr":"Makul bir adım ama önce alışkanlık gelir.","fa":"قدم خوبی است، ولی اول باید جزئیات خصوصی را حذف کنی."}},{"tone":"poor","text":"Then turn it on and paste everything.","next":"n2","reply":"Hm. Is that really enough?","feedback":{"en":"A setting doesn't make private data safe to paste.","tr":"Ayar özel bilgiyi güvenli yapmaz.","fa":"با تغییر تنظیمات، چسباندن اطلاعات خصوصی بی‌خطر نمی‌شود."}}]},"end":{"end":true,"outcome":{"en":"You kept private data out and gave a way forward.","tr":"Özel bilgileri dışarıda tuttun ve bir çözüm sundun.","fa":"نگذاشتی اطلاعات خصوصی وارد ابزار شود و راه‌حل هم دادی."}}}},"speaking":{"id":"ai-3","course":"ai-internet","unit":"ai-3","topic":{"en":"Explain the rule to a new colleague","tr":"Kuralı yeni bir meslektaşına anlat","fa":"قاعده را برای همکار جدید توضیح بده"},"warmup":{"en":"What information at your work should never leave the company?","tr":"İşinde hangi bilgiler şirketin dışına asla çıkmamalı?","fa":"در کارت چه اطلاعاتی هرگز نباید از شرکت بیرون برود؟"},"questions":[{"en":"Tell a new colleague what must stay out of AI tools and what to do instead.","tr":"Yeni bir meslektaşına yapay zekâ araçlarından neyin uzak tutulacağını ve bunun yerine ne yapılacağını anlat.","fa":"به همکار جدید بگو چه چیزی نباید وارد ابزارهای هوش مصنوعی شود و به‌جایش چه کند."},{"en":"Your colleague says: \"It's only one phone number.\" Say what you reply.","tr":"Meslektaşın diyor ki: \"It's only one phone number.\" Ne yanıt vereceğini söyle.","fa":"همکارت می‌گوید: «It's only one phone number.» بگو چه جوابی می‌دهی."},{"en":"In your own job, say one thing that is safe to paste and one that never is.","tr":"Kendi işinde yapıştırması güvenli bir şey ve asla güvenli olmayan bir şey söyle.","fa":"در کار خودت یک چیز بگو که چسباندنش بی‌خطر است و یکی که هرگز نیست."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"We must not paste...","meaning":{"en":"States a rule.","tr":"Bir kuralı söyler.","fa":"یک قاعده را می‌گوید."}},{"phrase":"Instead, use...","meaning":{"en":"Gives the other way.","tr":"Diğer yolu söyler.","fa":"راه دیگر را می‌گوید."}}],"model":"We must not paste passwords, customer names, phone numbers or contracts into any AI tool. Instead, use placeholders such as Customer and Order, then add the real details yourself at the end. If you're not sure, you can wait and ask your manager first. Settings can help, but a setting is not a guarantee, so the habit comes first.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I gave a rule and a way to do it.","tr":"Bir kural ve yapılış yolu söyledim.","fa":"یک قاعده و راه اجرایش را گفتم."}]},"writing":{"id":"c-ai-3-w","title":{"en":"Clean a text, then write the prompt","tr":"Metni temizle, sonra prompt yaz","fa":"متن را تمیز کن و بعد پرامپت بنویس"},"course":"ai-internet","unit":"ai-3","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Replace the private details with placeholders. Then write a prompt that asks for a short reply saying that we are checking it and will answer by a date. Text: \"Hasan Polat (hasan@mail.com) says invoice 882 for 4,300 TL is wrong.\"","tr":"Özel bilgileri yer tutucularla değiştir. Sonra kontrol ettiğimizi ve belirli bir tarihe kadar yanıt vereceğimizi söyleyen kısa bir yanıt isteyen prompt yaz. Metin: \"Hasan Polat (hasan@mail.com) says invoice 882 for 4,300 TL is wrong.\"","fa":"جزئیات خصوصی را با جای‌نگهدار عوض کن. بعد پرامپتی بنویس که از ابزار جوابی کوتاه بخواهد؛ جوابی که بگوید موضوع را بررسی می‌کنیم و تا تاریخ مشخصی خبر می‌دهیم. متن: «Hasan Polat (hasan@mail.com) says invoice 882 for 4,300 TL is wrong.»"},"model":"[Customer] says that [Invoice] for [Amount] is wrong. Write a short, polite reply. Say that we are checking it and will answer by [Date]. Under 50 words. Use only these facts.\n\nNote to myself: I have to add the real details before I send it.","frame":"[Customer] says ___. Write a short, polite reply. Say that ___. Under ___ words. Use only these facts.","words":[{"word":"[Customer]"},{"word":"Use only these facts"}],"minWords":25,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Add one policy sentence with unless.","tr":"B2 yolu: hazır çerçeve yok. unless içeren bir kural cümlesi ekle.","fa":"مسیر B2: چارچوب آماده نداری. یک جمله با unless برای بیان قاعده اضافه کن."},"own":{"en":"Now clean one real text from your work. Do not paste it anywhere.","tr":"Şimdi işinden gerçek bir metni temizle. Hiçbir yere yapıştırma.","fa":"حالا یک متن واقعی از کارت را تمیز کن. آن را جایی نچسبان."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Find the privacy words in your tool's settings and write down what they are called.","tr":"Aracının ayarlarında gizlilik kelimelerini bul ve adlarını yaz.","fa":"کلمه‌های حریم خصوصی را در تنظیمات ابزارت پیدا کن و بنویس اسمشان چیست."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the words Keep activity and Temporary chat from this lesson.","tr":"Bu dersteki Keep activity ve Temporary chat kelimelerini kullan.","fa":"از کلمه‌های Keep activity و Temporary chat در همین درس استفاده کن."},"noTool":true}]},"exit":{"id":"c-ai-3-x","course":"ai-internet","unit":"ai-3","type":"exit","items":[{"from":"ai-3","kind":"mcq","prompt":"What does Google tell you not to enter into Gemini?","options":["Anything you wouldn't want a reviewer to see","Any question on a topic you don't know well","Any public text that is longer than a page"],"correct":0,"why":{"en":"Anything you wouldn't want a reviewer to see: Google says people may review some chats. A topic you don't know well is fine to ask about; that is what the tool is for.","tr":"Anything you wouldn't want a reviewer to see: Google bazı sohbetleri insanların inceleyebileceğini söyler. İyi bilmediğin bir konuyu sormakta sakınca yoktur; araç zaten bunun için var.","fa":"گزینه‌ی Anything you wouldn't want a reviewer to see درست است، چون گوگل می‌گوید ممکن است آدم‌ها بعضی گفت‌وگوها را بخوانند. پرسیدن درباره‌ی موضوعی که خوب نمی‌شناسی اشکالی ندارد؛ ابزار اصلاً برای همین است."},"point":2},{"from":"ai-3","kind":"mcq","prompt":"Which sentence protects private data?","options":["[Customer] wants a refund.","Ali wants a refund for order 77.","Ali Sayar wants a refund."],"correct":0,"why":{"en":"[Customer] wants a refund: the placeholder keeps the real name out, and you put it back later. 'Ali wants a refund for order 77' still links a real person to an order.","tr":"[Customer] wants a refund: yer tutucu gerçek ismi dışarıda tutar, sen de sonra geri koyarsın. 'Ali wants a refund for order 77' hâlâ gerçek bir kişiyi bir siparişe bağlar.","fa":"[Customer] wants a refund درست است، چون جای‌نگهدار اسم واقعی را بیرون نگه می‌دارد و بعداً خودت اسم را برمی‌گردانی. جمله‌ی Ali wants a refund for order 77 هنوز یک آدم واقعی را به یک سفارش وصل می‌کند."},"point":5},{"from":"ai-3","kind":"blank","prompt":"You ___ share the admin password with any tool.","options":["must to","must not","don't have to"],"correct":1,"why":{"en":"must not: it is forbidden, and must not says exactly that. 'Don't have to' means it isn't necessary, so it would allow sharing.","tr":"must not: bu yasaktır ve must not tam olarak bunu söyler. 'Don't have to' gerekli değil demektir; yani paylaşmaya izin verir.","fa":"must not درست است، چون این کار ممنوع است و must not دقیقاً همین را می‌گوید. don't have to یعنی لازم نیست؛ پس اجازه‌ی این کار را می‌دهد."},"point":6},{"from":"ai-2","kind":"mcq","prompt":"The screen says \"File too large\". What can you do?","options":["Rename the file.","Paste a part of it.","Wait a few hours."],"correct":1,"why":{"en":"Paste a part of it: the file is over the size limit, so make it smaller or paste only what you need. Renaming changes the name, not the size.","tr":"Paste a part of it: dosya boyut sınırını aşıyor; küçült ya da yalnızca gereken kısmı yapıştır. Yeniden adlandırmak boyutu değil, adı değiştirir.","fa":"Paste a part of it درست است، چون حجم فایل از حد مجاز بیشتر است؛ پس کوچکش کن یا فقط بخشی را که لازم داری بچسبان. عوض کردن اسم فایل حجمش را کم نمی‌کند."},"point":4},{"from":"ai-2","kind":"blank","prompt":"I can't ___ this PDF.","options":["upload","to upload","uploading"],"correct":0,"why":{"en":"upload: after can't, use the base verb. 'To upload' adds to, and 'uploading' uses -ing; can't takes neither.","tr":"upload: can't'tan sonra yalın fiil gelir. 'To upload' to ekler, 'uploading' -ing kullanır; can't ikisini de almaz.","fa":"upload درست است، چون بعد از can't فعل ساده می‌آید. to upload یک to اضافه دارد و uploading شکل ing است؛ can't با هیچ‌کدام نمی‌آید."},"point":6},{"from":"ai-1","kind":"mcq","prompt":"All your mail is in Gmail. Which assistant do you look at first?","options":["Midjourney","Word","Gemini"],"correct":2,"why":{"en":"Gemini: it can connect to Google services such as Gmail, where your mail already is. Word is for writing documents, and Midjourney makes pictures.","tr":"Gemini: postanın zaten bulunduğu Gmail gibi Google hizmetlerine bağlanabilir. Word belge yazmak içindir, Midjourney ise resim yapar.","fa":"Gemini درست است، چون می‌تواند به سرویس‌های گوگل مثل Gmail وصل شود، همان‌جا که ایمیل‌هایت هست. Word برای نوشتن سند است و Midjourney تصویر می‌سازد."},"point":4}]},"explain":{"id":"c-ai-3-e","course":"ai-internet","unit":"ai-3","type":"explain","level":"B1","title":{"en":"Gemini: what stays out","tr":"Gemini: dışarıda kalması gerekenler","fa":"⁨Gemini⁩: چه چیزی نباید وارد ابزار شود"},"objective":{"en":"After this lesson, you can replace private details with placeholders and use the privacy words of AI tools.","tr":"Bu dersin sonunda özel bilgileri yer tutucularla değiştirebilecek ve yapay zekâ araçlarının gizlilik kelimelerini kullanabileceksin.","fa":"بعد از این درس می‌توانی جزئیات خصوصی را با جای‌نگهدار عوض کنی و کلمه‌های حریم خصوصی ابزارها را به کار ببری."},"hook":{"en":"Once you paste something into a tool, you can't be sure who may see it. So decide before you paste.","tr":"Bir şeyi araca yapıştırdıktan sonra kimin görebileceğinden emin olamazsın. Bu yüzden yapıştırmadan önce karar ver.","fa":"وقتی چیزی را در ابزار چسباندی، دیگر مطمئن نیستی چه کسی آن را می‌بیند. پس پیش از چسباندن تصمیم بگیر."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"25"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"6"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What Gemini is","tr":"Gemini nedir","fa":"⁨Gemini⁩ چیست"},"body":{"en":"Gemini is the AI assistant from Google. You chat with it at gemini.google.com or in its app.","tr":"Gemini, Google'ın yapay zekâ asistanıdır. gemini.google.com adresinde ya da uygulamasında onunla sohbet edersin.","fa":"⁨Gemini⁩ دستیار هوش مصنوعی گوگل است. در ⁨gemini.google.com⁩ یا اپلیکیشنش با آن چت می‌کنی."},"steps":[{"en":"It can work with your Gmail and Drive, but only if you connect them.","tr":"Gmail ve Drive'ınla çalışabilir, ama yalnızca sen bağlarsan.","fa":"می‌تواند با ⁨Gmail⁩ و ⁨Drive⁩ تو کار کند، ولی فقط اگر خودت وصلشان کنی.","ex":"Connected Apps"},{"en":"People may review some chats, so decide what you paste.","tr":"Bazı sohbetleri insanlar inceleyebilir; bu yüzden neyi yapıştıracağına karar ver.","fa":"ممکن است افرادی بعضی چت‌ها را بازبینی کنند، پس تصمیم بگیر چه چیزی را بچسبانی.","ex":"Keep activity"}],"tip":{"en":"As of October 2026. Tools change.","tr":"Ekim 2026 itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا اکتبر ۲۰۲۶. ابزارها تغییر می‌کنند."}},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What it is good for, and not","tr":"Neye yarar, neye yaramaz","fa":"به چه کاری می‌آید و به چه کاری نه"},"steps":[{"en":"Work that is already in Gmail, Docs or Drive","tr":"Zaten Gmail, Docs ya da Drive'da olan işler","fa":"کارهایی که همین حالا در ⁨Gmail⁩، ⁨Docs⁩ یا ⁨Drive⁩ هستند","ex":"Summarise this month's emails about the move."},{"en":"Making files such as documents, spreadsheets and PDFs","tr":"Belge, tablo ve PDF gibi dosyalar hazırlamak","fa":"ساختن فایل‌هایی مثل سند، جدول و ⁨PDF⁩","ex":"Turn my notes into a one-page document."},{"en":"Not the best: work that all lives in Microsoft files. Look at Copilot.","tr":"En iyisi değil: Tamamı Microsoft dosyalarında olan işler. Copilot'a bak.","fa":"بهترین گزینه نیست: کاری که همه‌اش در فایل‌های مایکروسافت است. سراغ ⁨Copilot⁩ برو.","ex":"Word and Excel files: look at Copilot."},{"en":"Not the best: confidential information. Google says not to enter anything you wouldn't want a reviewer to see.","tr":"En iyisi değil: Gizli bilgiler. Google, bir incelemecinin görmesini istemeyeceğin hiçbir şeyi girmemeni söylüyor.","fa":"بهترین گزینه نیست: اطلاعات محرمانه. گوگل می‌گوید چیزی را که نمی‌خواهی یک بازبین ببیند وارد نکن.","ex":"Would you show it to a stranger?"}]},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"How to start","tr":"Nasıl başlanır","fa":"چطور شروع کنی"},"steps":[{"en":"Go to gemini.google.com.","tr":"gemini.google.com adresine git.","fa":"به ⁨gemini.google.com⁩ برو."},{"en":"Some features work without signing in. For more, sign in with a Google account.","tr":"Bazı özellikler giriş yapmadan çalışır. Daha fazlası için Google hesabınla giriş yap.","fa":"بعضی امکانات بدون ورود کار می‌کنند. برای امکانات بیشتر با حساب گوگلت وارد شو."},{"en":"Type in the box at the bottom, then press Submit.","tr":"Alttaki kutuya yaz, sonra Submit'e bas.","fa":"در کادر پایین بنویس و بعد ⁨Submit⁩ را بزن."},{"en":"To start again, press New chat. If you can't see it, press Menu first.","tr":"Yeniden başlamak için New chat'e bas. Göremiyorsan önce Menu'ye bas.","fa":"برای شروع دوباره ⁨New chat⁩ را بزن. اگر آن را نمی‌بینی، اول ⁨Menu⁩ را بزن."}],"phrases":[{"phrase":"Turn my notes below into a one-page document with three headings:\nGoal, Decisions, Next steps.\nUse only my notes. If something is unclear, list it at the end.\nNotes: [paste notes, with names replaced by [Customer] or [Colleague]]","meaning":{"en":"It can make documents, and placeholders keep names out.","tr":"Belge hazırlayabilir, yer tutucular da adları dışarıda tutar.","fa":"می‌تواند سند بسازد و جای‌نگهدارها نمی‌گذارند نام‌ها وارد ابزار شوند."},"copy":true}],"tip":{"en":"No account, or it doesn't open? That's fine: the practice in this lesson uses fixed examples. More words and prompts are in this tool's guide.","tr":"Hesabın yok ya da açılmıyor mu? Sorun değil: Bu dersin uygulamasında sabit örnekler var. Diğer kelimeler ve prompt'lar bu aracın rehberinde.","fa":"حساب نداری یا باز نمی‌شود؟ اشکالی ندارد: تمرین‌های این درس نمونه‌های آماده دارند. کلمه‌ها و پرامپت‌های بیشتر در راهنمای این ابزار هستند."}},{"head":{"en":"What never goes in","tr":"Asla girmemesi gerekenler","fa":"چیزی که هرگز نباید وارد ابزار کنی"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"What you paste leaves your computer. Depending on the tool and its settings, it may be stored, used to train the AI or seen by a reviewer. You can't take it back, so decide first.","tr":"Yapıştırdığın şey bilgisayarından çıkar. Araca ve ayarlara göre saklanabilir, yapay zekâyı eğitmek için kullanılabilir ya da bir incelemeci görebilir. Geri alamazsın, bu yüzden önce karar ver.","fa":"چیزی که می‌چسبانی از رایانه‌ات بیرون می‌رود. بسته به ابزار و تنظیماتش، ممکن است ذخیره شود، برای آموزش هوش مصنوعی به کار برود یا یک بازبین آن را ببیند. نمی‌توانی پسش بگیری، پس اول تصمیم بگیر."},"steps":[{"en":"Passwords and ID numbers","tr":"Parolalar ve kimlik numaraları","fa":"رمز عبور و شماره‌ی شناسایی"},{"en":"Customers' names and contacts","tr":"Müşteri adları ve iletişim bilgileri","fa":"نام و اطلاعات تماس مشتری‌ها"},{"en":"Contracts, and prices that are not public","tr":"Sözleşmeler ve açıklanmamış fiyatlar","fa":"قراردادها و قیمت‌های غیرعمومی"}],"tip":{"en":"DeepSeek is another general AI assistant, and you may hear about it at work. Its privacy policy says personal data is stored in China. Read the privacy page of any tool, and follow the same rule: nothing private goes in.","tr":"DeepSeek başka bir genel yapay zekâ asistanıdır; iş yerinde adını duyabilirsin. Gizlilik politikası, kişisel verilerin Çin'de saklandığını söylüyor. Her aracın gizlilik sayfasını oku ve aynı kurala uy: özel bilgi girme.","fa":"⁨DeepSeek⁩ هم یک دستیار عمومی هوش مصنوعی است و شاید در محل کار اسمش را بشنوی. سیاست حفظ حریم خصوصی‌اش می‌گوید داده‌های شخصی در چین نگه داشته می‌شوند. صفحه‌ی حریم خصوصی هر ابزاری را بخوان و همان قاعده را رعایت کن: هیچ چیز خصوصی را وارد نکن."}},{"head":{"en":"Replace, paste, put back","tr":"Değiştir, yapıştır, geri koy","fa":"عوض کن، بچسبان، برگردان"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"A placeholder is a label that stands for the real detail.","tr":"Yer tutucu, gerçek bilginin yerini tutan bir etikettir.","fa":"جای‌نگهدار برچسبی است که به‌جای جزئیات واقعی می‌آید.","ex":"Ayşe Kaya becomes [Customer]."},{"en":"Replace first. Then paste. Then put the real details back yourself.","tr":"Önce değiştir. Sonra yapıştır. Gerçek bilgileri sonra kendin geri koy.","fa":"اول عوض کن. بعد بچسبان. جزئیات واقعی را بعداً خودت برگردان.","ex":"[Customer] wants a refund for [Order]."}],"tip":{"en":"Keep activity and temporary chats are useful words, but they don't replace this habit. Follow your company's rule first.","tr":"Keep activity ve temporary chat işe yarar kelimelerdir, ama bu alışkanlığın yerini tutmazlar. Önce şirketinin kuralına uy.","fa":"⁨Keep activity⁩ و چت موقت کلمه‌های مفیدی‌اند، ولی جای این عادت را نمی‌گیرند. اول به مقررات شرکتت عمل کن."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Rules at work: must not, have to, it's safe to","tr":"İş kuralları: must not, have to, it's safe to","fa":"قواعد کاری: ⁨must not⁩، ⁨have to⁩، ⁨it's safe to⁩"},"steps":[{"en":"must not means it is forbidden.","tr":"must not yasak demektir.","fa":"⁨must not⁩ یعنی ممنوع است.","ex":"You must not share this password."},{"en":"don't have to means it is not necessary.","tr":"don't have to gerekli değil demektir.","fa":"⁨don't have to⁩ یعنی لازم نیست.","ex":"You don't have to turn it off."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["must not + verb","We must not paste customer names."],["have to + verb","I have to remove the phone number first."],["It's safe to + verb","It's safe to paste the public price list."]]},"wrong":"You don't have to paste client names into the tool.","right":"You must not paste client names into the tool."}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Replace the private details","tr":"Özel bilgileri değiştir","fa":"جزئیات خصوصی را عوض کن"},"item":"Ayşe Kaya, 0532 000 00 00, wants a refund for order 4471.\nJob: a short, polite reply.","answer":"[Customer] wants a refund for [Order]. Write a short, polite reply.","walk":[{"en":"Find names, numbers and contacts.","tr":"Ad, numara ve iletişim bilgilerini bul.","fa":"نام‌ها، شماره‌ها و اطلاعات تماس را پیدا کن."},{"en":"Replace each one with a label.","tr":"Her birini bir etiketle değiştir.","fa":"هر کدام را با یک برچسب عوض کن."},{"en":"Ask: does the tool still have what it needs?","tr":"Sor: Aracın gerekli bilgisi hâlâ var mı?","fa":"از خودت بپرس: هر چه ابزار برای این کار لازم دارد هنوز در متن هست؟"}],"why":{"en":"The first version sends a real person's name and phone number. The second sends only labels, and the tool can still write the reply.","tr":"İlk sürüm gerçek bir kişinin adını ve telefonunu gönderir. İkincisi yalnızca etiket gönderir ve araç yine de yanıtı yazabilir.","fa":"نسخه‌ی اول نام و تلفن یک آدم واقعی را می‌فرستد. نسخه‌ی دوم فقط برچسب می‌فرستد و ابزار باز هم می‌تواند جواب را بنویسد."}},"quick":{"prompt":"Your team's work is all in Gmail and Drive. You want a summary of this month's emails about one project. What fits?","options":["Gemini with Connected Apps, if your company allows it.","Perplexity, because it gives numbered links.","A temporary chat, because it keeps everything."],"correct":0,"why":{"en":"Gemini can use Gmail and Drive, but only if you connect them.","tr":"Gemini, Gmail ve Drive'ı kullanabilir, ama yalnızca sen bağlarsan.","fa":"⁨Gemini⁩ می‌تواند از ⁨Gmail⁩ و ⁨Drive⁩ استفاده کند، ولی فقط اگر خودت وصلشان کنی."}},"quickAfter":3,"remember":{"en":"A setting is not a guarantee, so take private details out first. You can now clean a text before you paste it, and still get the reply you need.","tr":"Ayar bir güvence değildir, bu yüzden önce özel bilgileri çıkar. Artık bir metni yapıştırmadan önce temizleyebilir ve yine de istediğin yanıtı alabilirsin.","fa":"تنظیمات تضمین نیستند، پس اول جزئیات خصوصی را حذف کن. حالا می‌توانی متن را پیش از چسباندن تمیز کنی و باز هم جوابی را که لازم داری بگیری."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Stating a policy: be not allowed to, unless","tr":"Politika belirtmek: be not allowed to, unless","fa":"بیان مقررات: ⁨be not allowed to⁩، ⁨unless⁩"},"steps":[{"en":"be not allowed to is a formal rule.","tr":"be not allowed to resmî bir kuraldır.","fa":"با ⁨be not allowed to⁩ یک قاعده‌ی رسمی را می‌گویی.","ex":"We are not allowed to upload it."},{"en":"unless means except if.","tr":"unless \"-medikçe\" demektir.","fa":"⁨unless⁩ یعنی مگر اینکه.","ex":"Don't upload it unless it is public."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["be not allowed to","Staff are not allowed to paste contracts."],["unless + present","Don't share it unless your manager agrees."]]},"body":{"en":"B2: add one policy sentence with unless to your prompt note.","tr":"B2: Prompt notuna unless içeren bir kural cümlesi ekle.","fa":"⁨B2⁩: به یادداشت پرامپتت یک جمله با ⁨unless⁩ برای بیان قاعده اضافه کن."}},"tool":"gemini"}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
